from lib import *
S = SS('f116')
R = J('f116'); pf = R['perf']
steps = [
    step("model_validate 的转换与错误(pydantic 2.13.5):price 的字符串 \"1.50\" 转成 Decimal('1.50');缺字段 → qty: missing、price: missing;多个字段出错一次全报(name: string_too_short、qty: greater_than_equal、price: decimal_parsing);qty = \"5\" → 5,qty = 5.0 → 5,qty = True → 1(宽松模式),qty = 5.5 → 错误 int_from_float(和 marshmallow 把 5.5 截断不同);多余字段 extra 默认被悄悄忽略;tags 里的数字 → tags.1: string_type(loc 用路径)。一条错误是 {type, loc, msg, input, ctx}。", t=tl(S(1)), done=lidx(S(1), '合法', 'qty = "5"', 'qty = 5.0', '多余字段'), mark=lidx(S(1), '缺字段', '多个字段', 'qty = 5.5', 'tags'), kv=KV([['宽松模式', '"5" → 5,5.0 → 5,True → 1'], ['5.5', 'int_from_float 错误'], ['多余字段', '默认忽略']], ['5.5'])),
    step("bool 的转换:'true'、'1'、'yes' → True,'false'、'0'、'off' → False,'abc'、2、'maybe' → 错误。strict=True 的模型(ConfigDict(strict=True))对 \"5\"、5.0、True 都报错,宽松模式依次得到 5、5、1。需要拒绝「看起来像」的输入时开严格模式。", t=tl(S(2)), done=lidx(S(2), "'true'", "'false'", "'yes'", "'off'", '宽松'), mark=lidx(S(2), "'abc'", "'maybe'", 'strict=True'), kv=KV([['宽松', '字符串与数字会转换'], ['strict=True', '类型必须完全匹配']], ['strict=True'])),
    step("放进 Flask 的坑:把 e.errors() 直接 jsonify 会 500——请求体是 bytes 时 errors() 里的 input 是 bytes(非法 JSON 的情况),自定义校验器抛 ValueError 时 ctx 里是异常对象,都不能序列化。解决:e.errors(include_url=False, include_context=False, include_input=False) 得到干净的 422(只有 loc、msg、type),或者用 e.json(),它能处理这些类型。age 越界与 extra='forbid' 的多余字段这两种常规错误直接 jsonify 就能工作。", t=tl(S(3)), mark=lidx(S(3), '非法 JSON  ', '自定义校验器 ValueError'), done=lidx(S(3), 'include_input=False', '用 e.json()', 'age 越界', 'extra 被禁止'), kv=KV([['直接 jsonify(e.errors())', '遇到 bytes 或异常对象就 500'], ['include_* = False / e.json()', '安全']], ['直接 jsonify(e.errors())'])),
    step("查询参数:request.args.to_dict() 把重复的参数只留一个值,?ids=1&ids=2&page=3 传给 ids: list[int] 得到 list_type 错误;自己用 getlist 取出 ids(其余用 get),得到 ids=[1, 2] page=3。MultiDict 转模型要自己处理多值参数。", t=tl(S(4)), mark=lidx(S(4), 'to_dict'), done=lidx(S(4), 'getlist'), kv=KV([['to_dict()', '丢掉重复参数'], ['getlist', '多值参数要自己处理']], ['to_dict()'])),
    step("序列化:model_dump() 保留 datetime 与 Decimal 对象,model_dump(mode='json') 得到字符串('2026-01-02T03:04:05'、'1.10');Field(exclude=True) 的 password 在两种 dump 里都没有;model_json_schema() 直接给出 JSON Schema(properties 与 required,可用于文档,见第 114 篇)——注意 schema 里仍然列着 password,exclude 只影响 dump。", t=tl(S(5)), done=lidx(S(5), 'model_dump', 'model_json_schema'), kv=KV([["mode='json'", '得到可 JSON 化的值'], ['Field(exclude=True)', 'dump 时排除'], ['model_json_schema', '直接生成 schema']], ["mode='json'"])),
    step(f"性能:校验 10000 个字典,逐个 model_validate {pf[0]:.1f} ms,TypeAdapter(list[Item]) 一次校验整个列表 {pf[1]:.1f} ms;model_dump 10000 个 {pf[2]:.1f} ms。pydantic 的核心是 Rust 实现的;和上一篇 marshmallow dump 10000 个对象的 16.5 ms 不是同一个操作,不能直接比较。", b=bars([['逐个 model_validate', pf[0], f'{pf[0]:.1f} ms'], ['TypeAdapter 整个列表', pf[1], f'{pf[1]:.1f} ms'], ['model_dump', pf[2], f'{pf[2]:.1f} ms']], pf[0], done=[1, 2], mark=[0]), t=tl(S(6)), done=lidx(S(6), 'TypeAdapter'), kv=KV([['10000 个字典校验', f'{pf[0]:.1f} ms'], ['整个列表一次校验', f'{pf[1]:.1f} ms']], ['10000 个字典校验'])),
]
A = mkartf('f116', 116, 'Flask,Pydantic,校验,序列化,真实验证,动画演示',
    f'用 pydantic 2.13.5 实测 Flask 中的校验与序列化:宽松模式的类型转换与 int_from_float 错误、bool 的接受范围与 strict、直接 jsonify(e.errors()) 会因 bytes 与异常对象而 500、request.args.to_dict 丢掉重复参数、model_dump(mode=json) 与 exclude、校验 10000 个字典 {pf[0]:.1f} ms。',
    'Pydantic 在 Flask 里怎么用?错误信息能直接返回给客户端吗?宽松模式会转换哪些输入?这篇把踩过的坑(包括我自己第一次写出的 500)和每种输入的结果逐项打印出来。',
    [('500', '直接 jsonify(e.errors()) 遇到 bytes 的 input 或异常对象的 ctx 时的状态码'), ('5.5', 'pydantic 对 int 字段报 int_from_float 错误,而 marshmallow 会截断'), (f'{pf[0]:.1f} ms', '逐个校验 10000 个字典的耗时')],
    [('转换与错误', '<p>上一篇:<a href="flask-marshmallow-serialization.html">Marshmallow 序列化</a>;下一篇:<a href="flask-large-json-response.html">大批量 JSON 响应</a>。</p>'), ('bool 与严格模式', None), ('放进 Flask', None), ('查询参数', None), ('序列化', None), ('性能', None)],
    steps, [ENV_F + '。pydantic 2.13.5', '没有验证:与 Flask-Pydantic、flask-openapi3 等封装库的行为、自定义类型与 discriminated union、模型继承与 computed_field、异步校验、pydantic-settings 读取配置'], 'Pydantic 在 Flask 中', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
